import csv, glob, json, os, re, unicodedata
from datetime import date
import pandas as pd

DATA_DIR = '/app/data'
OUT_DIR = '/app/output'

# column indexes per file: id, date, amount, category, region
CONFIGS = {
    'eu_export.csv':           dict(delim=',',  header=True,  cols=(0,1,2,3,4), dayfirst=True),
    'legacy_dump.csv':         dict(delim=',',  header=True,  cols=(4,2,3,1,0), dayfirst='auto'),
    'nordic_export.csv':       dict(delim=';',  header=True,  cols=(0,1,2,3,4), dayfirst=False),
    'partner_feed.csv':        dict(delim=',',  header=True,  cols=(0,1,2,3,4), dayfirst=False),
    'raw_export.txt':          dict(delim='|',  header=False, cols=(4,0,3,2,1), dayfirst=True),
    'sales_report_feb.csv':    dict(delim=',',  header=True,  cols=(0,1,2,3,4), dayfirst=False),
    'tab_export.tsv':          dict(delim='\t', header=True,  cols=(0,1,2,3,4), dayfirst=False),
    'transactions_2023_q1.csv':dict(delim=',',  header=True,  cols=(0,1,2,3,4), dayfirst=False),
    'weekly_export_2023.csv':  dict(delim=',',  header=True,  cols=(0,1,2,3,4), dayfirst=False),
}

def read_lines(path):
    for enc in ('utf-8', 'latin-1'):
        try:
            with open(path, encoding=enc) as fh:
                return fh.read().splitlines()
        except UnicodeDecodeError:
            continue
    with open(path, encoding='utf-8', errors='replace') as fh:
        return fh.read().splitlines()

def parse_id(s):
    s = (s or '').strip()
    if not s:
        return None
    try:
        return int(s)
    except ValueError:
        pass
    try:
        f = float(s)
        return int(f) if f.is_integer() else None
    except ValueError:
        return None

def parse_date(s, dayfirst):
    s = (s or '').strip()
    if not s:
        return None
    toks = re.split(r'[-/.]', s)
    if len(toks) != 3:
        return None
    if len(toks[0]) == 4:  # year first
        y, m, d = toks
    else:
        y = toks[2]
        df = dayfirst
        if df == 'auto':  # legacy: dash -> day first, slash -> month first (US)
            df = '-' in s
        if df:
            d, m = toks[0], toks[1]
        else:
            m, d = toks[0], toks[1]
    try:
        return date(int(y), int(m), int(d)).isoformat()
    except ValueError:
        return None

def parse_amount(s):
    s = (s or '').strip()
    if not s:
        return None
    s = re.sub(r'(?i)usd', '', s)
    for ch in ('$', '€', '£', ' ', '\xa0', '"'):
        s = s.replace(ch, '')
    if ',' in s and '.' in s:
        if s.rfind(',') > s.rfind('.'):
            s = s.replace('.', '').replace(',', '.')
        else:
            s = s.replace(',', '')
    elif ',' in s:
        s = s.replace(',', '.')
    try:
        return float(s)
    except ValueError:
        return None

def norm_category(s):
    if s is None:
        return None
    s = s.strip()
    if not s:
        return None
    t = unicodedata.normalize('NFKD', s)
    t = ''.join(c for c in t if not unicodedata.combining(c)).lower()
    if 'book' in t or 'livre' in t:
        return 'Books'
    if 'cloth' in t or 'vetement' in t:
        return 'Clothing'
    if 'electr' in t:
        return 'Electronics'
    if 'food' in t or 'aliment' in t:
        return 'Food'
    if 'sport' in t:
        return 'Sports'
    return s

def norm_region(s):
    if s is None:
        return None
    s = s.strip()
    if not s or s.upper() in ('N/A', 'NA', 'NONE', 'NULL', '-'):
        return None
    return s

records = []
total_raw = 0
for path in sorted(glob.glob(os.path.join(DATA_DIR, '*'))):
    name = os.path.basename(path)
    cfg = CONFIGS[name]
    lines = read_lines(path)
    rows = list(csv.reader(lines, delimiter=cfg['delim']))
    if cfg['header'] and rows:
        rows = rows[1:]
    ci, cd, ca, cc, cr = cfg['cols']
    for row in rows:
        if not row or all(not (x or '').strip() for x in row):
            continue
        total_raw += 1
        rid = parse_id(row[ci] if ci < len(row) else '')
        if rid is None:
            continue  # drop only missing/unparseable id
        records.append({
            'id': rid,
            'order_date': parse_date(row[cd] if cd < len(row) else '', cfg['dayfirst']),
            'amount': parse_amount(row[ca] if ca < len(row) else ''),
            'category': norm_category(row[cc] if cc < len(row) else None),
            'region': norm_region(row[cr] if cr < len(row) else None),
        })

df = pd.DataFrame(records, columns=['id', 'order_date', 'amount', 'category', 'region'])
df = df.drop_duplicates(subset='id', keep='first').reset_index(drop=True)
df['id'] = df['id'].astype('int64')
df['amount'] = df['amount'].astype('float64')

os.makedirs(OUT_DIR, exist_ok=True)
df.to_parquet(os.path.join(OUT_DIR, 'clean.parquet'), index=False, engine='pyarrow')

dates = df['order_date'].dropna()
summary = {
    'total_rows': int(len(df)),
    'total_rows_raw': int(total_raw),
    'date_range': {'min': str(dates.min()) if len(dates) else None,
                   'max': str(dates.max()) if len(dates) else None},
    'categories': sorted(df['category'].dropna().unique().tolist()),
    'regions': sorted(df['region'].dropna().unique().tolist()),
    'total_amount': round(float(df['amount'].sum()), 2),
}
with open(os.path.join(OUT_DIR, 'summary.json'), 'w') as fh:
    json.dump(summary, fh, indent=2)
print(json.dumps(summary, indent=2))
PYEOF
